/**
 * Unit tests for SimplexTableau#discardArtificialVariables.
 * Since the method is protected, we use a Test subclass to expose it.
 */
public class SimplexTableau_discardArtificialVariables_TriageGen0Test {

    private TestableSimplexTableau tableau;

    /**
     * A subclass to allow testing protected methods and mocking internal state.
     */
    private static class TestableSimplexTableau extends SimplexTableau {
        private int numArtificialVariables;
        private RealMatrix tableau;

        protected TestableSimplexTableau(int width, int height, int numArtificialVariables, int rhsOffset) {
            // We use a mock or a dummy implementation because SimplexTableau constructor 
            // is complex and requires specific internal states.
            // However, since we want to test the logic of discardArtificialVariables, 
            // we will mock the behavior of the getter methods.
            this.numArtificialVariables = numArtificialVariables;
            this.tableau = null;
        }

        // Expose protected method for testing
        @Override
        public void discardArtificialVariables() {
            super.discardArtificialVariables();
        }

        // Setters for testing purposes
        public void setNumArtificialVariables(int n) { this.numArtificialVariables = n; }
        public void setTableau(RealMatrix m) { this.tableau = m; }
        public void setWidth(int w) { /* Not directly possible via field, we mock getWidth */ }
    }

    // Because SimplexTableau is complex, the most reliable way to test this specific 
    // logic without triggering constructor errors is to use Mockito to spy on a real object
    // or a subclass where we control the return values of the protected getters.

    @Before
    public void setUp() {
        // We use a spy on a subclass to control the behavior of protected methods used in the logic
    }

    @Test
    public void testDiscardArtificialVariables_WhenNumArtificialVariablesIsZero() {
        // Arrange
        SimplexTableau spyTableau = spy(new TestableSimplexTableau(0, 0, 0, 0) {
            @Override
            public int getWidth() { return 5; }
            @Override
            public int getHeight() { return 3; }
            @Override
            public int getNumArtificialVariables() { return 0; }
        });

        // Act
        spyTableau.discardArtificialVariables();

        // Assert
        // If numArtificialVariables is 0, it should return early. 
        // No changes to tableau or other logic should occur.
        verify(spyTableau, never()).getEntry(anyInt(), anyInt());
    }

    @Test
    public void testDiscardArtificialVariables_Success() {
        // Arrange
        // Setup dimensions: 
        // height = 3, width = 5, numArtificialVariables = 2, rhsOffset = 4
        // Expected new width = 5 - 2 - 1 = 2
        // Expected new height = 3 - 1 = 2
        // matrix[i][j] comes from getEntry(i+1, j+1)
        // matrix[i][width-1] comes from getEntry(i+1, getRhsOffset())

        int numArt = 2;
        int width = 5;
        int height = 3;
        int rhsOffset = 4;

        SimplexTableau spyTableau = spy(new TestableSimplexTableau(width, height, numArt, rhsOffset) {
            @Override
            public int getWidth() { return width; }
            @Override
            public int getHeight() { return height; }
            @Override
            public int getNumArtificialVariables() { return numArt; }
            @Override
            public int getRhsOffset() { return rhsOffset; }
            @Override
            public double getEntry(int row, int col) {
                if (row == 1 && col == 1) return 10.0;
                if (row == 1 && col == 4) return 20.0;
                if (row == 2 && col == 1) return 30.0;
                if (row == 2 && col == 4) return 40.0;
                return 0.0;
            }
        });

        // Act
        spyTableau.discardArtificialVariables();

        // Assert
        // Check if getEntry was called correctly to build the matrix
        // The loop for j runs up to width - 1 (which is 2). 
        // Inside loop: j < width - 1 - 1 (since width is calculated as width - numArt - 1)
        // Let's trace the actual code logic:
        // width_new = 5 - 2 - 1 = 2.
        // height_new = 3 - 1 = 2.
        // matrix is 2x2.
        // i=0: j=0: matrix[0][0] = getEntry(1, 1) = 10.0
        //      j loop ends (j < 2-1=1)
        //      matrix[0][1] = getEntry(1, 4) = 20.0
        // i=1: j=0: matrix[1][0] = getEntry(2, 1) = 30.0
        //      j loop ends
        //      matrix[1][1] = getEntry(2, 4) = 40.0

        // Since we cannot easily inspect the private 'tableau' field of the real SimplexTableau 
        // without reflection, we verify the interactions that prove the logic executed.
        verify(spyTableau).getEntry(1, 1);
        verify(spyTableau).getEntry(1, 4);
        verify(spyTableau).getEntry(2, 1);
        verify(spyTableau).getEntry(2, 4);

        // Verify numArtificialVariables is reset to 0 via the side effect if possible, 
        // but since it's protected, we rely on the fact that the method completed.
    }
}
